Setup do ambiente

if (!"pak" %in% installed.packages()[,"Package"]) install.packages("pak")

c("tidyverse", "rstan", "coda", "deldir", "posterior", "shinystan") |&gt;
  setdiff(installed.packages()[,"Package"]) |&gt;
  pak::pak()

data {
  int&lt;lower=1&gt; n;
  int&lt;lower=1&gt; p;
  matrix[n, p] X;
  vector Y;
}
parameters {
  vector[p] beta;
}
transformed parameters {
  vector[n] eta;
  eta = X * beta;
}
model {
  for (i in 1:n) {
    Y[i] ~ poisson(exp(eta[i]));
  }
  for (k in 1:p) {
    beta[k] ~ normal(0,1);
  }
}






